    noResults: 'Ничего не найдено.',
    noneInGroup: 'В этой группе пусто.',
    pickCron: 'Выберите задание слева — покажу расписание, исходник и ближайшие запуски.',
    loading: 'Загружаю каталог…',
    failed: 'Каталог не прочитан:',
    backToLibrary: 'Все задания',
    filterAll: 'Все',
    healthOk: 'Работает',
    healthWarn: 'Работает с оговоркой',
    healthFail: 'Не работает',
